-- 0006_product_codes
-- SKUs and barcodes are generated by the system (and not typed by hand), so they are always
-- unique and consistent. Each business gets a counter; every new product takes the next number.
--   SKU      <PREFIX>-000123          e.g. GF-000123 for Go-fish
--   Barcode  EAN-13, "29" + 10 digits + check digit. 29x numbers are reserved for in-store use,
--            so they can never clash with a manufacturer's barcode on goods.
-- Products that already have a barcode keep it; the rest get one here.

ALTER TABLE businesses ADD COLUMN product_seq bigint NOT NULL DEFAULT 0;

CREATE FUNCTION pg_temp_ean13(body text) RETURNS text LANGUAGE sql IMMUTABLE AS $$
  SELECT ((10 - (sum(substr(body, i, 1)::int * CASE WHEN i % 2 = 1 THEN 1 ELSE 3 END) % 10)) % 10)::text
    FROM generate_series(1, 12) AS i
$$;

-- Number every existing product per business (oldest first) and give barcode-less ones a barcode.
WITH numbered AS (
  SELECT id, business_id, row_number() OVER (PARTITION BY business_id ORDER BY created_at, id) AS n
    FROM products
)
UPDATE products p
   SET barcode = '29' || lpad(numbered.n::text, 10, '0') || pg_temp_ean13('29' || lpad(numbered.n::text, 10, '0'))
  FROM numbered
 WHERE p.id = numbered.id AND p.barcode IS NULL;

UPDATE businesses b
   SET product_seq = COALESCE((SELECT count(*) FROM products p WHERE p.business_id = b.id), 0);

DROP FUNCTION pg_temp_ean13(text);
